from workflow import *
from PIL import Image,ImageFilter
name='r13_c12_stair_cross_joint_v02'
old=ROOT/'guides/r13_c12_stair_cross_joint_v01.png'
guide=Image.open(old).convert('RGB')
# GUIDE ONLY. Suppress the failed discontinuity while retaining registered outer actual source pixels.
blur=guide.filter(ImageFilter.GaussianBlur(24))
guide.paste(blur.crop((150,300,1104,1104)),(150,300))
gf=ROOT/'guides'/f'{name}.png';assert not gf.exists();guide.save(gf)
write(Path(str(gf)+'.generation.json'),{'file':str(gf),'sha256':sha(gf),'usableAsFinalArt':False,'operation':'Blur only failed staircase interior in a registered guide; actual outer source pixels retained; no edited pixels permitted in final output.','derivedFrom':str(old),'derivedFromSha256':sha(old),'guideOnlyBlurBox':[150,300,1104,1104]})
prompt='''Regenerate the two COMPLETE real wooden pier landing objects inside image1 at unchanged 1254-square coordinates, daylight opaque painted art. The blurred center marks the failed geometry to reconstruct; this guide itself cannot be final art. Exact crisp OUTERMOST115 at left/right/top/bottom already contains the correct finished adjacent art. Match those outer contours precisely without narrowing the lower platform. There are TWO broad wooden landing levels. UPPER full floor: golden front edge enters left near y480 and exits right near y250; connect with a clean coherent full wooden beam and straight board boundaries, no haze/ghost stripe under it. LOWER full platform: its BACK edge enters left near y700 and exits right near y580; its FRONT bright edge enters left near y1130 and exits right near y880. It is a very BROAD real walking surface, about350-430px deep, with a full black plank groove across its middle. Draw the ENTIRE broad top surface between those boundaries, filled with honey wood. Do not change its left portion into sea, do not narrow it into a thin rail or delete half its boards. Build coherent full perspective from both fixed outer ends. Between the upper front beam and lower BACK edge there is open BLUE SEA, and below the lower front beam there is open BLUE SEA. Existing short supports remain; no extra support/cap/post. The large left column and its wooden attachment are fixed. Every floor groove must be physically complete and connect to a genuine board end or continue across the full surface. No step at former x627 seam, no floating groove, no patch of transparent/faded golden wood over water. Clean rounded contours, restrained painted grain and matching daylight blue waves. Final3 images are original layout, materials and style references, no layout expansion, zoom, text, UI, people or animals.'''
refs=[{'file':str(gf),'sha256':sha(gf),'role':'whole staircase guide; only blurred center requires native redraw'}]+read(ROOT/'references.json')
pf=ROOT/'prompts'/f'{name}.prompt.txt';assert not pf.exists();pf.write_text(prompt,encoding='utf-8')
write(ROOT/'prompts'/f'{name}.request.json',{'tile':'r13_c12','tileRelativeOrigin':[1421,909],'promptPath':str(pf),'references':refs,'transparent_background':False,'submittedParameters':{'model':None,'quality':None}})
write(ROOT/'prompts'/f'{name}.args.json',{'prompt':prompt,'referenced_image_paths':[r['file'] for r in refs],'transparent_background':False})
write(ROOT/'qa/r13-stair-cross-v01/root-review.json',{'status':'rejected_not_adopted','reason':'Upper front beam contains soft golden ghost stripe, lower landing left portion deleted into sea at outer cut; right and north contours pass but whole object fails.','source':str(ROOT/'native/r13_c12_stair_cross_joint_v01.png'),'sourceSha256':sha(ROOT/'native/r13_c12_stair_cross_joint_v01.png'),'reviewedCuts':['left.png','right.png','top.png'],'formalAccepted':False})
print(str(gf))
